# phs/baiying/live_project.py
from __future__ import annotations

import json
import os
import tempfile
import uuid
import zipfile
from copy import deepcopy
from datetime import datetime, timezone
from pathlib import Path
from threading import RLock
from typing import Any, Dict, List, Optional

from fastapi import APIRouter, File, HTTPException, UploadFile
from fastapi.responses import FileResponse
from pydantic import BaseModel, Field


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _dump(model: BaseModel) -> Dict[str, Any]:
    if hasattr(model, "model_dump"):
        return model.model_dump(exclude_none=True)
    return model.dict(exclude_none=True)


class ProjectCreate(BaseModel):
    name: str = Field(..., min_length=1)
    scene: str = "default"
    asset_ids: List[str] = Field(default_factory=list)
    script_ids: List[str] = Field(default_factory=list)
    products: List[Dict[str, Any]] = Field(default_factory=list)
    config: Dict[str, Any] = Field(default_factory=dict)
    tags: List[str] = Field(default_factory=list)
    meta: Dict[str, Any] = Field(default_factory=dict)


class ProjectUpdate(BaseModel):
    name: Optional[str] = None
    scene: Optional[str] = None
    asset_ids: Optional[List[str]] = None
    script_ids: Optional[List[str]] = None
    products: Optional[List[Dict[str, Any]]] = None
    config: Optional[Dict[str, Any]] = None
    tags: Optional[List[str]] = None
    meta: Optional[Dict[str, Any]] = None


class ProjectStore:
    def __init__(self, path: Optional[str] = None):
        default_path = Path("data") / "live_project" / "projects.json"
        self.path = Path(path or os.getenv("PHS_LIVE_PROJECT_DB", default_path))
        self.lock = RLock()
        self.data: Dict[str, Any] = {"projects": []}
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self._load()

    def _load(self) -> None:
        if not self.path.exists():
            self._save()
            return
        try:
            self.data = json.loads(self.path.read_text(encoding="utf-8"))
            self.data.setdefault("projects", [])
        except Exception:
            self.path.replace(self.path.with_suffix(".corrupt.json"))
            self.data = {"projects": []}
            self._save()

    def _save(self) -> None:
        tmp = self.path.with_suffix(".tmp")
        tmp.write_text(json.dumps(self.data, ensure_ascii=False, indent=2), encoding="utf-8")
        tmp.replace(self.path)

    def _find_index(self, project_id: str) -> int:
        for i, item in enumerate(self.data["projects"]):
            if item.get("id") == project_id:
                return i
        return -1

    @staticmethod
    def _dedupe(values: List[str]) -> List[str]:
        seen, result = set(), []
        for value in values or []:
            if value not in seen:
                seen.add(value)
                result.append(value)
        return result

    def list(self, scene: Optional[str] = None, q: Optional[str] = None) -> List[Dict[str, Any]]:
        with self.lock:
            items = deepcopy(self.data["projects"])
        if scene:
            items = [x for x in items if x.get("scene") == scene]
        if q:
            ql = q.lower()
            items = [
                x for x in items
                if ql in (x.get("name", "") + x.get("scene", "") + " ".join(x.get("tags", []))).lower()
            ]
        return sorted(items, key=lambda x: x.get("updated_at", ""), reverse=True)

    def get(self, project_id: str) -> Dict[str, Any]:
        with self.lock:
            idx = self._find_index(project_id)
            if idx < 0:
                raise KeyError(project_id)
            return deepcopy(self.data["projects"][idx])

    def create(self, payload: ProjectCreate) -> Dict[str, Any]:
        item = _dump(payload)
        item["id"] = uuid.uuid4().hex
        item["asset_ids"] = self._dedupe(item.get("asset_ids", []))
        item["script_ids"] = self._dedupe(item.get("script_ids", []))
        item["tags"] = sorted(set(item.get("tags", [])))
        item["created_at"] = _now()
        item["updated_at"] = item["created_at"]
        with self.lock:
            self.data["projects"].append(item)
            self._save()
            return deepcopy(item)

    def update(self, project_id: str, payload: ProjectUpdate) -> Dict[str, Any]:
        patch = _dump(payload)
        with self.lock:
            idx = self._find_index(project_id)
            if idx < 0:
                raise KeyError(project_id)
            item = self.data["projects"][idx]
            item.update(patch)
            if "asset_ids" in patch:
                item["asset_ids"] = self._dedupe(item.get("asset_ids", []))
            if "script_ids" in patch:
                item["script_ids"] = self._dedupe(item.get("script_ids", []))
            if "tags" in patch:
                item["tags"] = sorted(set(item.get("tags", [])))
            item["updated_at"] = _now()
            self._save()
            return deepcopy(item)

    def delete(self, project_id: str) -> Dict[str, Any]:
        with self.lock:
            idx = self._find_index(project_id)
            if idx < 0:
                raise KeyError(project_id)
            item = self.data["projects"].pop(idx)
            self._save()
            return deepcopy(item)

    def import_project(self, item: Dict[str, Any], rename: Optional[str] = None) -> Dict[str, Any]:
        item = deepcopy(item)
        item["id"] = uuid.uuid4().hex
        if rename:
            item["name"] = rename
        item["asset_ids"] = self._dedupe(item.get("asset_ids", []))
        item["script_ids"] = self._dedupe(item.get("script_ids", []))
        item["tags"] = sorted(set(item.get("tags", [])))
        item["imported_at"] = _now()
        item["created_at"] = _now()
        item["updated_at"] = item["created_at"]
        with self.lock:
            self.data["projects"].append(item)
            self._save()
            return deepcopy(item)


class TemplateExporter:
    def __init__(self, export_dir: Optional[str] = None):
        default_dir = Path("data") / "live_project" / "exports"
        self.export_dir = Path(export_dir or os.getenv("PHS_LIVE_PROJECT_EXPORT_DIR", default_dir))
        self.export_dir.mkdir(parents=True, exist_ok=True)

    def export(self, project: Dict[str, Any]) -> Path:
        safe_name = "".join(c for c in project.get("name", "project") if c.isalnum() or c in "-_") or "project"
        filename = f"{safe_name}_{project.get('id', uuid.uuid4().hex)[:8]}.zip"
        out_path = self.export_dir / filename
        manifest = {
            "template_type": "phs_live_project",
            "version": "0.1.0",
            "exported_at": _now(),
            "project_id": project.get("id"),
            "project_name": project.get("name"),
            "scene": project.get("scene"),
            "asset_count": len(project.get("asset_ids", [])),
            "script_count": len(project.get("script_ids", [])),
            "product_count": len(project.get("products", [])),
            "files": ["manifest.json", "project.json"],
        }
        with zipfile.ZipFile(out_path, "w", zipfile.ZIP_DEFLATED) as zf:
            zf.writestr("manifest.json", json.dumps(manifest, ensure_ascii=False, indent=2))
            zf.writestr("project.json", json.dumps(project, ensure_ascii=False, indent=2))
        return out_path


class TemplateImporter:
    def load(self, zip_bytes: bytes) -> Dict[str, Any]:
        with tempfile.TemporaryDirectory() as tmp:
            zip_path = Path(tmp) / "template.zip"
            zip_path.write_bytes(zip_bytes)
            try:
                with zipfile.ZipFile(zip_path, "r") as zf:
                    names = set(zf.namelist())
                    if "manifest.json" not in names:
                        raise ValueError("manifest.json not found")
                    manifest = json.loads(zf.read("manifest.json").decode("utf-8"))
                    if manifest.get("template_type") != "phs_live_project":
                        raise ValueError("invalid template_type")
                    if "project.json" in names:
                        project = json.loads(zf.read("project.json").decode("utf-8"))
                    else:
                        project = manifest.get("project")
                    if not isinstance(project, dict):
                        raise ValueError("project data not found")
                    project.pop("id", None)
                    project.pop("created_at", None)
                    project.pop("updated_at", None)
                    return project
            except zipfile.BadZipFile:
                raise ValueError("invalid zip file")


def create_live_project_router(store: Optional[ProjectStore] = None, prefix: str = "") -> APIRouter:
    db = store or ProjectStore()
    exporter = TemplateExporter()
    importer = TemplateImporter()
    router = APIRouter(prefix=prefix, tags=["live-project"])

    @router.get("/projects")
    def list_projects(scene: Optional[str] = None, q: Optional[str] = None) -> Dict[str, Any]:
        items = db.list(scene=scene, q=q)
        return {"items": items, "count": len(items)}

    @router.post("/projects")
    def create_project(payload: ProjectCreate) -> Dict[str, Any]:
        return db.create(payload)

    @router.post("/projects/import")
    async def import_project(file: UploadFile = File(...), rename: Optional[str] = None) -> Dict[str, Any]:
        try:
            project = importer.load(await file.read())
            item = db.import_project(project, rename=rename)
            return {"imported": True, "item": item}
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=str(exc))

    @router.get("/projects/{project_id}")
    def get_project(project_id: str) -> Dict[str, Any]:
        try:
            return db.get(project_id)
        except KeyError:
            raise HTTPException(status_code=404, detail="project not found")

    @router.put("/projects/{project_id}")
    def update_project(project_id: str, payload: ProjectUpdate) -> Dict[str, Any]:
        try:
            return db.update(project_id, payload)
        except KeyError:
            raise HTTPException(status_code=404, detail="project not found")

    @router.delete("/projects/{project_id}")
    def delete_project(project_id: str) -> Dict[str, Any]:
        try:
            return {"deleted": True, "item": db.delete(project_id)}
        except KeyError:
            raise HTTPException(status_code=404, detail="project not found")

    @router.get("/projects/{project_id}/export")
    def export_project(project_id: str) -> FileResponse:
        try:
            path = exporter.export(db.get(project_id))
            return FileResponse(path, media_type="application/zip", filename=path.name)
        except KeyError:
            raise HTTPException(status_code=404, detail="project not found")

    return router


class LiveProjectTemplateProvider:
    provider_id = "live_project"
    name = "Live Project Template"
    version = "0.1.0"

    def __init__(self, config: Optional[Dict[str, Any]] = None):
        self.config = config or {}
        self.store = ProjectStore(self.config.get("db_path"))
        self.exporter = TemplateExporter(self.config.get("export_dir"))
        self.importer = TemplateImporter()
        self.router = create_live_project_router(self.store)

    def get_router(self) -> APIRouter:
        return self.router

    def health(self) -> Dict[str, Any]:
        return {
            "provider": self.provider_id,
            "ok": True,
            "db_path": str(self.store.path),
            "project_count": len(self.store.data.get("projects", [])),
        }

    def metadata(self) -> Dict[str, Any]:
        return {
            "id": self.provider_id,
            "name": self.name,
            "version": self.version,
            "routes": ["/projects", "/projects/{id}/export", "/projects/import"],
        }


def create_provider(config: Optional[Dict[str, Any]] = None) -> LiveProjectTemplateProvider:
    return LiveProjectTemplateProvider(config)


